<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    --memory-swap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">256m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\ </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 禁止容器使用 swap,避免性能雪崩</span></span>
